 async function copyLink(path){try{await navigator.clipboard.writeText(new URL(path,location.origin).href);notice=tr('링크를 복사했습니다.','Link copied.');}catch{notice=tr('주소 표시줄의 링크를 복사해 공유하세요.','Copy the address bar link to share this page.');history.replaceState({},'',path);routeSignature='';}draw();}
 document.addEventListener('click',event=>{
  const el=event.target.closest?.('[data-learn-tab],[data-learn-chapter],[data-learn-rule],[data-learn-bookmark],[data-learn-ref],[data-learn-copy],[data-learn-clear-rule],[data-learn-category],[data-learn-lesson],[data-learn-step],[data-learn-exit-lesson],[data-learn-prev],[data-learn-next],[data-learn-complete],[data-learn-restart],[data-learn-cancel-restart],[data-learn-confirm-restart],[data-learn-print],[data-learn-download],[data-learn-hint-toggle]');if(!el||!active())return;event.preventDefault();event.stopImmediatePropagation();loadProgress();
  if(el.hasAttribute('data-learn-tab')){query='';category='all';onlyBookmarks=false;navigate({tab:el.dataset.learnTab,chapter:'',rule:'',lesson:'',step:0});}
  else if(el.hasAttribute('data-learn-chapter'))navigate({chapter:el.dataset.learnChapter,rule:''});
  else if(el.hasAttribute('data-learn-rule'))navigate({rule:el.dataset.learnRule,chapter:''});
  else if(el.hasAttribute('data-learn-clear-rule'))navigate({rule:'',chapter:''});
  else if(el.hasAttribute('data-learn-bookmark')){const id=el.dataset.learnBookmark;progress.bookmarkEvents[id]={saved:!progress.bookmarks.includes(id),at:tick()};saveProgress();draw();}
  else if(el.hasAttribute('data-learn-ref'))window.MMRuleReference?.open(el.dataset.refKind,el.dataset.learnRef,{edition:el.dataset.refEdition,activator:el});
  else if(el.hasAttribute('data-learn-copy'))copyLink(el.dataset.learnCopy);
  else if(el.hasAttribute('data-learn-category')){category=el.dataset.learnCategory;current.sheet='all';updateResults();}
  else if(el.hasAttribute('data-learn-lesson')){const lesson=allLessons().find(l=>l.id===el.dataset.learnLesson);if(lesson){const p=lessonProgress(lesson);navigate({tab:'tutorials',lesson:lesson.id,step:p.completed?0:Number(p.checkpoint)||0});}}
  else if(el.hasAttribute('data-learn-step')){const lesson=currentLesson();if(lesson){const step=Math.min(Math.max(Number(el.dataset.learnStep)||0,0),lesson.steps.length-1),p=lessonProgress(lesson);p.checkpoint=step;putLesson(lesson,p);navigate({step});}}
  else if(el.hasAttribute('data-learn-hint-toggle')){tutorialUi.hint=!tutorialUi.hint;draw();document.querySelector('[data-learn-hint-toggle]')?.focus({preventScroll:true});}
  else if(el.hasAttribute('data-learn-exit-lesson'))navigate({lesson:'',step:0});
  else if(el.hasAttribute('data-learn-prev'))navigate({step:Math.max(0,current.step-1)});
  else if(el.hasAttribute('data-learn-complete')){if(markStep())draw();}
  else if(el.hasAttribute('data-learn-next')){const lesson=currentLesson();if(markStep())navigate(current.step===lesson.steps.length-1?{lesson:'',step:0}:{step:current.step+1});}
  else if(el.hasAttribute('data-learn-restart')){restartId=el.dataset.learnRestart;draw();}
  else if(el.hasAttribute('data-learn-cancel-restart')){restartId='';draw();}
  else if(el.hasAttribute('data-learn-confirm-restart')){const key=current.edition+':'+el.dataset.learnConfirmRestart;progress.lessonResets[key]=tick();delete progress.lessons[key];saveProgress();navigate({step:0});}
  else if(el.hasAttribute('data-learn-download'))downloadGuide();
  else if(el.hasAttribute('data-learn-print')){document.body.classList.add('ukl-printing');try{window.print();}catch{document.body.classList.remove('ukl-printing');notice=tr('인쇄 창을 열지 못했습니다. 브라우저 인쇄 메뉴를 사용해 주세요.','The print dialog could not open. Use your browser print menu.');draw();}}
 },true);
 document.addEventListener('toggle',event=>{if(!active()||!event.target.matches?.('[data-learn-example],[data-learn-pitfalls],[data-learn-toc]'))return;const el=event.target;if(!el.isConnected)return;if(el.hasAttribute('data-learn-example'))tutorialUi.example=el.open;else if(el.hasAttribute('data-learn-pitfalls'))tutorialUi.pitfalls=el.open;else tutorialUi.toc=el.open;},true);
 document.addEventListener('input',event=>{if(!event.target.matches?.('[data-learn-search]')||!active())return;query=event.target.value;updateResults();});
 document.addEventListener('change',event=>{if(!active())return;const el=event.target;if(el.matches('[data-learn-edition]')){query='';category='all';onlyBookmarks=false;navigate({edition:el.value==='n23'?'n23':'n26',chapter:'',rule:'',lesson:'',step:0,sheet:'all'});}else if(el.matches('[data-learn-saved]')){onlyBookmarks=el.checked;updateResults();}else if(el.matches('[data-learn-answer]')){const lesson=currentLesson();if(!lesson)return;const step=lesson.steps[current.step],p=lessonProgress(lesson);if(!step.exercise?.options?.some(o=>o.id===el.dataset.learnAnswer))return;p.answers[step.id]=el.dataset.learnAnswer;p.checkpoint=current.step;putLesson(lesson,p);draw();[...document.querySelectorAll('[data-learn-answer]')].find(node=>node.dataset.learnAnswer===el.dataset.learnAnswer)?.focus({preventScroll:true});}});
 window.addEventListener('popstate',()=>{routeSignature='';if(!/^\/learn(?:\/|$)/.test(location.pathname))document.body.classList.remove('ukl-printing');if(/^\/learn(?:\/|$)/.test(location.pathname)){if(typeof data!=='undefined')data.view='learning';draw();}});
